def excluded(path: Path) -> tuple[bool, str]:
    relative = path.relative_to(ROOT)
    for part in relative.parts:
        if part in SKIP_DIRS:
            return True, SKIP_DIRS[part]
    lowered = relative.as_posix().lower()
    if path.suffix not in SOURCE_SUFFIXES:
        return True, "non-executable file type"
    if ".test." in lowered or "/tests/" in f"/{lowered}":
        return True, "test fixture; audited separately by hostile-path suite"
    if lowered == "scripts/check_mind_invocation_surface.py":
        return True, "the scanner cannot audit its own signatures"
    return False, ""


def enclosing_symbol(lines: list[str], number: int) -> str:
    symbols = re.compile(r"^\s*(?:async\s+def|def|class|export\s+(?:async\s+)?function|export\s+class|function)\s+([\w$]+)")
    for line in reversed(lines[:number]):
        match = symbols.search(line)
        if match:
            return match.group(1)
    return "<module>"


def infer_runtime(mechanism: str, source: str) -> tuple[str, str, str]:
    lowered = source.lower()
    if "ollama" in lowered or "/api/chat" in lowered or "/api/generate" in lowered:
        return "ollama-compatible", "ollama/local", "LOCAL_HTTP"
    if "openai" in lowered or "/v1/" in lowered:
        return "openai-compatible", "unresolved", "REMOTE_HTTP"
    if "anthropic" in lowered:
        return "anthropic-compatible", "anthropic", "REMOTE_HTTP"
    if "subprocess" in lowered:
        return "local-model-runner", "local", "SUBPROCESS"
    return mechanism.lower(), "unresolved", "OTHER"


def discover() -> tuple[list[dict[str, object]], dict[str, str]]:
    rows: list[dict[str, object]] = []
    exclusions = dict(SKIP_DIRS)
    paths: list[Path] = []
    for directory, names, files in os.walk(ROOT):
        names[:] = [name for name in names if name not in SKIP_DIRS]
        paths.extend(Path(directory) / name for name in files)
    for path in sorted(paths):
        skip, reason = excluded(path)
        if skip:
            continue
        relative = path.relative_to(ROOT).as_posix()
        try:
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue
        for number, line in enumerate(lines, 1):
            mechanisms = [name for name, pattern in SIGNATURES if pattern.search(line)]
            if BYPASS.search(line):
                mechanisms.append("SEMANTIC_BYPASS")
            if not mechanisms:
                continue
            mechanism = "+".join(mechanisms)
            imports_conduit = any(
                "mind_conduit_runtime import" in candidate
                for candidate in lines[: min(number, 120)]
            )
            governed_call = any(
                item in mechanisms
                for item in ("MIND_CONDUIT_CALL", "GOVERNED_ADAPTER_CALL", "GOVERNED_DCX_CALL")
            )
            classification = (
                "AUTHORIZED"
                if relative in AUTHORIZED or (imports_conduit and governed_call)
                else "UNAUTHORIZED"
            )
            runtime, provider, transport = infer_runtime(mechanism, line)
            symbol = enclosing_symbol(lines, number)
            if relative in {
                "front/app/src/lib/mind/dcx-adapter.ts",
                "front/app/src/lib/mind/mind-conduit.ts",
            }:
                history_class = "ORIGINAL_AUTHORIZED"
            elif relative == "back/services/grid/mind_conduit_runtime.py":
                history_class = "NEWLY_DISCOVERED_NEWLY_AUTHORIZED"
            else:
                history_class = "MIGRATED_FORMERLY_UNAUTHORIZED"
            surface_id = hashlib.sha256(f"{relative}:{number}:{line.strip()}".encode()).hexdigest()[:16]
            rows.append({
                "surface_id": surface_id,
                "source_file": relative,
                "line_or_symbol": f"{number}:{symbol}",
                "symbol_or_line": f"{symbol}:{number}",
                "entrypoint": symbol,
                "caller": "MindConduit" if relative.endswith("mind-conduit.ts") else symbol,
                "model_or_runtime": runtime,
                "provider": provider,
                "transport": transport,
                "invocation_mechanism": mechanism,
                "passes_through_mind_conduit": relative in AUTHORIZED,
                "binding_enforced": relative in AUTHORIZED,
                "invocation_capability_required": relative in AUTHORIZED,
                "identity_effect": "UNRESOLVED",
                "memory_access": "UNRESOLVED",
                "provenance_access": "UNRESOLVED",
                "constitution_access": "UNRESOLVED",
                "adjudication_effect": "UNRESOLVED",
                "permission_effect": "UNRESOLVED",
                "sense_access": "UNRESOLVED",
                "state_effect": "UNRESOLVED",
                "purpose": "UNRESOLVED",
                "sovereignty_impact": "GOVERNED_MODEL_EXECUTION_BOUNDARY",
                "capability_impact": "MODEL_INFERENCE",
                "what_it_can_see": "UNRESOLVED",
                "what_it_can_retrieve": "UNRESOLVED",
                "what_it_can_propose": "UNRESOLVED",
                "what_it_can_change": "UNRESOLVED",
                "what_it_can_remember": "UNRESOLVED",
                "current_disposition": "CONDUIT_INTERNAL" if classification == "AUTHORIZED" else "REMEDIATION_REQUIRED",
                "authorized_or_unauthorized": classification,
                "evidence_ref": f"{relative}:{number}",
                "historical_gate_name": "INVOCATION_AUDIT",
                "current_gate_name": "INVOCATION_SURFACE_GUARD",
                "history_notes": "Identifiers remain separate pending Claude adjudication.",
                "surface_history_class": history_class,
                "source_excerpt": line.strip()[:240],
            })
    return rows, exclusions


def verify_moscript_runtime_map() -> tuple[bool, list[dict[str, object]]]:
    mapping_path = ROOT / "core/ops/status/MOSCRIPT_RUNTIME_IMPLEMENTATION_MAP.json"
    document = json.loads(mapping_path.read_text(encoding="utf-8"))
    results: list[dict[str, object]] = []
    for mapping in document["mappings"]:
        source = ROOT / mapping["moscript_source"]
        implementation = ROOT / mapping["implementation_file"]
        source_digest = hashlib.sha256(source.read_bytes()).hexdigest() if source.is_file() else None
        implementation_digest = hashlib.sha256(implementation.read_bytes()).hexdigest() if implementation.is_file() else None
        symbol_present = implementation.is_file() and mapping["implementation_symbol"] in implementation.read_text(encoding="utf-8")
        valid = (
            source_digest == mapping["moscript_source_digest"]
            and implementation_digest == mapping["implementation_digest"]
            and symbol_present
        )
        results.append({**mapping, "verified": valid})
    return all(item["verified"] for item in results), results


